let rawRespuesta = $('Agente Principal').first().json.output || "";

if (typeof rawRespuesta === 'string') {
    const jsonMatch = rawRespuesta.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
        rawRespuesta = jsonMatch[0]; 
    }
}

return [{
  json: {
    user_id: $('Convertir mensaje').first().json.id_usuario,
    message: $('Convertir Entrada').first().json.mensaje_usuario,
    respuesta: rawRespuesta
  }
}];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const inputData = $input.first().json;;

const historialPrevio = inputData.historial_sesion || [];
const nuevoMensaje = `Usuario: ${inputData.message}\nAgente: ${inputData.respuesta}`;
historialPrevio.push(nuevoMensaje);

return [{
  json: {
    user_id: inputData.user_id,
    historial_sesion: historialPrevio,
    ultima_respuesta: inputData.respuesta
  }
}];

const catalog = $input.first().json.catalog;

const groupedItems = catalog.reduce((acc, item) => {
  const categoryName = item.categoria;

  if (!acc[categoryName]) {
    acc[categoryName] = { 
      categoria: categoryName, 
      productos: [] 
    };
  }

  item.productos.forEach((pro) => {
    let product = acc[categoryName].productos.find(p => p.titulo === pro.titulo);

    if (!product) {
      product = { 
        titulo: pro.titulo, 
        colores: pro.colores || [] 
      };
      acc[categoryName].productos.push(product);
    } else {
      if (pro.colores) {
        product.colores.push(...pro.colores);
      }
    }
  });

  return acc;
}, {});

const result = Object.values(groupedItems);
return result.map((item) => ({ json: item }));

const inputData = $('uso imagen producto').first().json;
const catalog = inputData.catalog;

// Forzamos la búsqueda de productos con una ruta más directa
const products = (catalog && catalog.length > 0) ? catalog[0].productos : [];

const folders = $('Productos categoria').all();

if (!Array.isArray(products) || products.length === 0) {
  // Si no hay productos, devolvemos un mensaje claro en lugar de nada
  return [{ json: { mensaje: "El array de productos está vacío o no se encontró" } }];
}

const result = products.map((item, index) => {
  // Usamos trim() por si hay espacios invisibles
  const tittle = item.titulo.toUpperCase().trim();
  const folderMatch = folders.find(x => x.json.name.toUpperCase().trim() === tittle);

  return {
    json: {
      titulo: tittle,
      idFolder: folderMatch ? folderMatch.json.id : null,
      paired: !!folderMatch
    },
    pairedItem: {
      item: index
    }
  };
});

return result;

// 1. Convertimos el texto que sale del agente en un objeto real
const data = JSON.parse($('Agente Principal').item.json.output);
const now = Date.now();

// 2. Ahora sí podemos extraer los datos
return {
  process_id: "coordinating_agent",
  model_name: data.model_name,
  prompt_tokens: data.prompt_tokens,
  completion_tokens: data.completion_tokens,
  total_tokens: data.total_tokens,
  ai_response: data.ai_response || data.replyText,
  completed_at: now,
  created_at: now,
  environment: 'ist'
};

// 1. Obtenemos el texto del agente
let rawOutput = $('Agente Principal').item.json.output;
let data = {};

if (typeof rawOutput === 'string') {
    try {
        // Limpiamos el texto de espacios o saltos de línea al inicio/fin
        let cleanedOutput = rawOutput.trim();

        // Extraemos estrictamente lo que hay entre la primera '{' y la última '}'
        const jsonMatch = cleanedOutput.match(/\{[\s\S]*\}/);

        if (jsonMatch) {
            // Si el agente mandó un JSON correctamente, lo extraemos y lo convertimos
            cleanedOutput = jsonMatch[0];
            data = JSON.parse(cleanedOutput);
        } else {
            // PLAN B: Si no hay llaves, significa que mandó texto puro. 
            // Lo metemos directamente en replyText.
            data = { replyText: cleanedOutput };
        }

    } catch (error) {
        // PLAN C: Si intentó parsear un JSON pero estaba roto, salvamos el mensaje original.
        console.error("Error al parsear el JSON:", error);
        data = { replyText: rawOutput }; 
    }
} else {
    // Si ya venía como objeto, lo asignamos directamente
    data = rawOutput || {};
}

// 2. Obtenemos la lista plana de productos que viene en el input
let rawCatalog = [];
if (data.catalog){
  rawCatalog = Array.isArray(data.catalog) ? data.catalog : [data.catalog];
}

// 3. Retornamos el objeto final
return {
  replyText: data.replyText || "",
  sendImage: !!data.sendImage,
  imagenproducto: !!data.imagenproducto,
  categoria: data.categoria || "COCHES",
  catalog: rawCatalog
};
